PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    OverloadOK : BOOL;
END_VAR

Motor := (Start OR Motor) AND (NOT Stop) AND OverloadOK;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Stop : BOOL;
    Start : BOOL;
END_VAR

Motor := NOT Stop AND (Start OR Motor);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT (Stop OR Overload);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
    EStop : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT (Stop OR Overload OR EStop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

Motor := ((Start OR Motor) AND NOT Stop) AND NOT EStop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := (Start AND NOT Stop) OR (Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := Start AND NOT Stop OR Motor AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Stop : BOOL;
    Start : BOOL;
END_VAR

Motor := NOT Stop AND Start OR NOT Stop AND Motor;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    StopNC : BOOL;
END_VAR

Motor := (Start OR Motor) AND StopNC;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    StopNC : BOOL;
    OL_NC : BOOL;
END_VAR

Motor := (Start OR Motor) AND StopNC AND OL_NC;

END_PROGRAM

PROGRAM Main
VAR
    Fwd : BOOL;
    FwdPB : BOOL;
    Stop : BOOL;
    Rev : BOOL;
    RevPB : BOOL;
END_VAR

Fwd := (FwdPB OR Fwd) AND NOT Stop AND NOT Rev AND NOT RevPB;
Rev := (RevPB OR Rev) AND NOT Stop AND NOT Fwd AND NOT FwdPB;

END_PROGRAM

PROGRAM Main
VAR
    Fwd : BOOL;
    FwdPB : BOOL;
    Stop : BOOL;
    Rev : BOOL;
    RevPB : BOOL;
END_VAR

Fwd := (FwdPB OR Fwd) AND NOT (Stop OR Rev);
Rev := (RevPB OR Rev) AND NOT (Stop OR Fwd);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Lamp : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;
Lamp := Start OR (Lamp AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    StartPB : BOOL;
    StopPB : BOOL;
    RunLamp : BOOL;
    PilotLight : BOOL;
END_VAR

Motor := (StartPB OR Motor) AND NOT StopPB;
RunLamp := StartPB OR (RunLamp AND NOT StopPB);
PilotLight := Motor;

END_PROGRAM

PROGRAM Main
VAR
    PartCounter : CTU;
    PartSensor : BOOL;
    Start : BOOL;
    Motor : BOOL;
    Stop : BOOL;
END_VAR

PartCounter(CU := PartSensor, RESET := Start, PV := 50);
Motor := (Start OR Motor) AND NOT Stop AND NOT PartCounter.Q;

END_PROGRAM

PROGRAM Main
VAR
    StartDelay : TON;
    StartPB : BOOL;
    Compressor : BOOL;
    StopPB : BOOL;
END_VAR

StartDelay(IN := (StartPB OR Compressor) AND NOT StopPB, PT := T#2S);
Compressor := StartDelay.Q;

END_PROGRAM

PROGRAM Main
VAR
    StartEdge : R_TRIG;
    StartPB : BOOL;
    Motor : BOOL;
    StopPB : BOOL;
END_VAR

StartEdge(CLK := StartPB);
Motor := StartEdge.Q OR (Motor AND NOT StopPB);

END_PROGRAM

PROGRAM Main
VAR
    StartEdge : R_TRIG;
    StartPB : BOOL;
    StartPulse : BOOL;
    Motor : BOOL;
    StopPB : BOOL;
END_VAR

StartEdge(CLK := StartPB, Q => StartPulse);
Motor := StartPulse OR (Motor AND NOT StopPB);

END_PROGRAM

PROGRAM Main
VAR
    StartPulse : BOOL;
    StartPB : BOOL;
    StartOld : BOOL;
    Motor : BOOL;
    StopPB : BOOL;
END_VAR

StartPulse := StartPB AND NOT StartOld;
StartOld := StartPB;
Motor := StartPulse OR (Motor AND NOT StopPB);

END_PROGRAM

PROGRAM Main
VAR
    StartOS : BOOL;
    StartPB : BOOL;
    StartMem : BOOL;
    Motor : BOOL;
    StopPB : BOOL;
END_VAR

StartOS := StartPB AND NOT StartMem;
StartMem := StartPB;
Motor := StartOS OR (Motor AND NOT StopPB);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);
IF Stop THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);
Motor := Motor AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Stop : BOOL;
    Overload : BOOL;
    Motor : BOOL;
    Start : BOOL;
END_VAR

IF Stop OR Overload THEN
    Motor := FALSE;
ELSE
    Motor := Start OR (Motor AND NOT Stop);
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Stop : BOOL;
    Motor : BOOL;
    Start : BOOL;
END_VAR

IF NOT Stop THEN
    Motor := Start OR (Motor AND NOT Stop);
ELSE
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    PumpLatch : RS;
    StartPB : BOOL;
    StopPB : BOOL;
    Overload : BOOL;
    Pump : BOOL;
END_VAR

PumpLatch(S := StartPB, R1 := StopPB OR Overload);
Pump := PumpLatch.Q1;

END_PROGRAM

PROGRAM Main
VAR
    State : INT;
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
END_VAR

CASE State OF
    0: Motor := FALSE;
       IF Start AND NOT Stop THEN State := 1; END_IF;
    1: Motor := TRUE;
       IF Stop OR Overload THEN State := 0; END_IF;
END_CASE;

END_PROGRAM

PROGRAM Main
VAR
    State : INT;
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
    Motor : BOOL;
END_VAR

CASE State OF
    0: IF Start THEN State := 1; END_IF;
    1: IF Stop OR Overload THEN State := 0; END_IF;
END_CASE;
IF Stop OR Overload THEN State := 0; END_IF;
Motor := (State = 1);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

(* Seal-in. Written Start OR ( Motor AND NOT Stop ) it would let Start win, so: *)
Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

(* WRONG: Motor := Start OR (Motor AND NOT Stop); *)
Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

// old: Motor := Start OR (Motor AND NOT Stop);
Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Msg : STRING;
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Msg := 'Press Start OR (Stop) to change';
Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    HmiText : STRING;
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

HmiText := 'Motor := Start OR (Motor AND NOT Stop);';
Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    FeedbackFault : BOOL;
    AuxContact : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;
FeedbackFault := Motor XOR (AuxContact AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Jog : BOOL;
    Stop : BOOL;
END_VAR

Motor := (((Start AND NOT Jog) XOR (Jog AND NOT Start)) OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := (((Start) OR (Motor))) AND (NOT (Stop));

END_PROGRAM

PROGRAM Main
VAR
    SafetyOK : BOOL;
    EStop1 : BOOL;
    EStop2 : BOOL;
    GuardClosed : BOOL;
    Overload : BOOL;
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

SafetyOK := NOT EStop1 AND NOT EStop2 AND GuardClosed AND NOT Overload;
Motor := (Start OR Motor) AND NOT Stop AND SafetyOK;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    EStop1 : BOOL;
    EStop2 : BOOL;
    GuardClosed : BOOL;
    Overload : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop AND NOT (EStop1 OR EStop2) AND GuardClosed AND NOT Overload;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Permissive : BOOL;
    Stop : BOOL;
END_VAR

Motor := (Start AND Permissive OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor1 : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Motor2 : BOOL;
    Motor2Delay : TON;
END_VAR

Motor1 := (Start OR Motor1) AND NOT Stop;
Motor2 := (Motor1 AND Motor2Delay.Q OR Motor2) AND NOT Stop AND Motor1;
Motor2Delay(IN := Motor1, PT := T#5S);

END_PROGRAM

PROGRAM Main
VAR
    Stop : BOOL;
    Overload : BOOL;
    Motor : BOOL;
    Start : BOOL;
END_VAR

IF Stop OR Overload THEN
    Motor := FALSE;
ELSIF Start THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Stop : BOOL;
    Overload : BOOL;
    Running : BOOL;
    Motor : BOOL;
    Start : BOOL;
    Auto : BOOL;
    Manual : BOOL;
END_VAR

IF (Stop OR (Overload AND Running)) THEN
    Motor := FALSE;
ELSIF (Start AND (Auto OR Manual)) THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Start : BOOL;
    Ready : BOOL;
    Bypass : BOOL;
    Motor : BOOL;
    Stop : BOOL;
    Overload : BOOL;
    ResetPB : BOOL;
END_VAR

IF Start AND (Ready OR Bypass) THEN Motor := TRUE; END_IF;
IF Stop OR (Overload AND NOT ResetPB) THEN Motor := FALSE; END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

IF Start AND NOT Stop THEN
    Motor := TRUE;
ELSIF Stop THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
    Motor : BOOL;
END_VAR

IF Start AND NOT (Stop OR Overload) THEN
    Motor := TRUE;
ELSIF (Stop OR Overload) THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Start : BOOL;
    Motor : BOOL;
    Stop : BOOL;
END_VAR

IF Start AND NOT Motor THEN
    Motor := TRUE;
ELSIF Stop THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    RunLamp : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;
IF Start THEN RunLamp := TRUE; ELSIF Stop THEN RunLamp := FALSE; END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Pump : BOOL;
    PumpStartLevel : BOOL;
    PumpStopLevel : BOOL;
END_VAR

Pump := PumpStartLevel OR (Pump AND NOT PumpStopLevel);

END_PROGRAM

PROGRAM Main
VAR
    Heater : BOOL;
    StartPB : BOOL;
    StopPB : BOOL;
    OverTemp : BOOL;
END_VAR

Heater := (StartPB OR Heater) AND NOT StopPB AND NOT OverTemp;

END_PROGRAM

PROGRAM Main
VAR
    motor : BOOL;
    start : BOOL;
    stop : BOOL;
END_VAR

motor := (start or motor) and not stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor:=(Start OR Motor)AND NOT(Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

Motor := (Start
          OR Motor)
         AND NOT Stop
         AND NOT EStop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    JogMode : BOOL;
    Jog : BOOL;
END_VAR

Motor := ((Start OR Motor) AND NOT Stop AND NOT JogMode) OR (Jog AND JogMode AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    StartOK : BOOL;
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
    Motor : BOOL;
END_VAR

StartOK := Start AND NOT Stop AND NOT EStop;
Motor := StartOK OR (Motor AND NOT Stop AND NOT EStop);

END_PROGRAM

FUNCTION_BLOCK FB_Motor
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    OL : BOOL;
END_VAR
VAR_OUTPUT
    Run : BOOL;
END_VAR
Run := (Start OR Run) AND NOT Stop AND NOT OL;
END_FUNCTION_BLOCK

PROGRAM Main
VAR
    Motor : BOOL;
    AutoMode : BOOL;
    Start : BOOL;
    Stop : BOOL;
    AutoRun : BOOL;
END_VAR

Motor := SEL(AutoMode, (Start OR Motor) AND NOT Stop, AutoRun AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := Motor OR Start;
IF Stop THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Running : BOOL;
    Stop : BOOL;
END_VAR

Motor := (Start OR Motor AND Running) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Pump : BOOL;
    StartPB : BOOL;
    HmiStart : BOOL;
    StopPB : BOOL;
    HmiStop : BOOL;
END_VAR

Pump := (StartPB OR HmiStart OR Pump) AND NOT StopPB AND NOT HmiStop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Halt : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Halt;

END_PROGRAM

PROGRAM Main
VAR
    StopReq : BOOL;
    Stop : BOOL;
    EStop : BOOL;
    Overload : BOOL;
    Motor : BOOL;
    Start : BOOL;
END_VAR

StopReq := Stop OR EStop OR Overload;
Motor := (Start OR Motor) AND NOT StopReq;

END_PROGRAM

PROGRAM Main
VAR
    Latch : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

Latch := Start OR (Latch AND NOT Stop);
Motor := Latch AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    MotorCmd : BOOL;
    Start : BOOL;
    Stop : BOOL;
    MotorOut : BOOL;
END_VAR

MotorCmd := Start OR (MotorCmd AND NOT Stop);
IF Stop THEN MotorCmd := FALSE; END_IF;
MotorOut := MotorCmd;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Stop : BOOL;
    Start : BOOL;
END_VAR

Motor := NOT(Stop) AND (Start OR Motor);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    OL : BOOL;
END_VAR

Motor := (Start OR Motor)AND NOT(Stop OR OL);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Stop : BOOL;
    Start : BOOL;
END_VAR

Motor := NOT (Stop OR NOT (Start OR Motor));

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := NOT ((NOT Start AND NOT Motor) OR Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
    ResetPB : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop AND NOT (Overload AND NOT ResetPB);

END_PROGRAM

PROGRAM Main
VAR
    Mixer : BOOL;
    Start : BOOL;
    Stop : BOOL;
    LidClosed : BOOL;
    Maintenance : BOOL;
END_VAR

Mixer := (Start OR Mixer) AND NOT Stop AND (LidClosed OR Maintenance);

END_PROGRAM

PROGRAM Main
VAR
    StopNC : BOOL;
    OLok : BOOL;
    Motor : BOOL;
    StartPB : BOOL;
    Auto : BOOL;
END_VAR

IF NOT (StopNC AND OLok) THEN
    Motor := FALSE;
ELSIF StartPB OR (Motor AND Auto) THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    WarningStrobe : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;
WarningStrobe := Start OR (WarningStrobe AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

(* old (* v1 *) Motor := Start OR (Motor AND NOT Stop); *)
Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    RunTimer : TON;
END_VAR

Motor := (Start OR Motor) AND NOT Stop AND NOT RunTimer.Q;
RunTimer(IN := Motor, PT := T#10M);

END_PROGRAM

bool motor = false;
void setup() { pinMode(2, INPUT_PULLUP); pinMode(3, INPUT_PULLUP); pinMode(8, OUTPUT); }
void loop() {
  bool start = digitalRead(2) == LOW;
  bool stopPressed = digitalRead(3) == LOW;
  motor = (start || motor) && !stopPressed;
  digitalWrite(8, motor);
}

bool motor = false;
void setup() { pinMode(2, INPUT_PULLUP); pinMode(3, INPUT_PULLUP); pinMode(8, OUTPUT); }
void loop() {
  bool start = digitalRead(2) == LOW;
  bool stopPressed = digitalRead(3) == LOW;
  motor = start || (motor && !stopPressed);
  if (stopPressed) motor = false;
  digitalWrite(8, motor);
}

PROGRAM Main
VAR
    Saw : BOOL;
    StartPB : BOOL;
    StopPB : BOOL;
    EStop1 : BOOL;
    EStop2 : BOOL;
    GuardClosed : BOOL;
    Overload : BOOL;
END_VAR

Saw := (StartPB OR Saw) AND NOT StopPB AND NOT (EStop1 OR EStop2 OR NOT GuardClosed OR Overload);

END_PROGRAM

PROGRAM Main
VAR
    Conveyor : BOOL;
    RunCmd : BOOL;
    StopCmd : BOOL;
END_VAR

Conveyor := (RunCmd OR Conveyor) AND NOT StopCmd;

END_PROGRAM

PROGRAM Main
VAR
    Pump1 : BOOL;
    StartPB_1 : BOOL;
    StopPB_1 : BOOL;
    Pump1_OL : BOOL;
END_VAR

Pump1 := (StartPB_1 OR Pump1) AND NOT (StopPB_1 OR Pump1_OL);

END_PROGRAM

PROGRAM Main
VAR
    Start : BOOL;
    Motor : BOOL;
    Stop : BOOL;
    OL : BOOL;
END_VAR

IF Start THEN Motor := TRUE; ELSIF Stop THEN Motor := FALSE; END_IF;
Motor := Motor AND NOT (Stop OR OL);

END_PROGRAM

PROGRAM Main
VAR
    Start : BOOL;
    Motor : BOOL;
    Stop : BOOL;
    OL : BOOL;
    Running : BOOL;
END_VAR

IF Start THEN Motor := TRUE; ELSIF Stop THEN Motor := FALSE; END_IF;
IF (Stop OR (OL AND Running)) THEN Motor := FALSE; END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Stop : BOOL;
    Motor : BOOL;
    Start : BOOL;
END_VAR

IF Stop THEN Motor := FALSE; END_IF;
IF Start AND NOT (Stop) THEN Motor := TRUE; END_IF;

END_PROGRAM

PROGRAM Main
VAR
    Stop : BOOL;
    Motor : BOOL;
    Start : BOOL;
END_VAR

IF Stop THEN Motor := FALSE; END_IF;
IF (Start OR Motor) AND NOT Stop THEN Motor := TRUE; END_IF;

END_PROGRAM

PROGRAM Main
VAR
    EStopLatched : BOOL;
    EStop : BOOL;
    ResetPB : BOOL;
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

EStopLatched := EStop OR (EStopLatched AND NOT ResetPB);
Motor := (Start OR Motor) AND NOT Stop AND NOT EStopLatched;

END_PROGRAM

PROGRAM Main
VAR
    Pump : BOOL;
    HmiStart : BOOL;
    HmiStop : BOOL;
END_VAR

Pump := HmiStart OR (Pump AND NOT HmiStop);
HmiStart := FALSE;
HmiStop := FALSE;

END_PROGRAM

PROGRAM Main
VAR
    Stop : BOOL;
    Motor : BOOL;
    RETURN : BOOL;
    Start : BOOL;
END_VAR

IF Stop THEN
    Motor := FALSE;
    RETURN;
END_IF;
Motor := Start OR (Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    StartPB : BOOL;
    StopPB : BOOL;
END_VAR

Motor := StartPB OR (Motor AND NOT StopPB);

END_PROGRAM

PROGRAM Main
VAR
    Conveyor : BOOL;
    RunCmd : BOOL;
    StopCmd : BOOL;
END_VAR

Conveyor := RunCmd OR (Conveyor AND NOT StopCmd);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor := Start OR Motor AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop AND NOT Overload);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT (Stop OR EStop));

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Stop : BOOL;
    Start : BOOL;
END_VAR

Motor := (Motor AND NOT Stop) OR Start;

END_PROGRAM

PROGRAM Main
VAR
    motor : BOOL;
    start : BOOL;
    stop : BOOL;
END_VAR

motor := start or (motor and not stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
END_VAR

Motor:=Start OR(Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

Motor := StartPB
         OR (Motor
             AND NOT StopPB
             AND NOT EStop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    StopNC : BOOL;
END_VAR

Motor := Start OR (Motor AND StopNC);

END_PROGRAM

PROGRAM Main
VAR
    Fwd : BOOL;
    FwdPB : BOOL;
    Stop : BOOL;
    Rev : BOOL;
    RevPB : BOOL;
END_VAR

Fwd := FwdPB OR (Fwd AND NOT Stop AND NOT Rev);
Rev := RevPB OR (Rev AND NOT Stop AND NOT Fwd);

END_PROGRAM

PROGRAM Main
VAR
    Fwd : BOOL;
    FwdPB : BOOL;
    Rev : BOOL;
    Stop : BOOL;
    RevPB : BOOL;
END_VAR

Fwd := (FwdPB AND NOT Rev) OR (Fwd AND NOT Stop);
Rev := (RevPB AND NOT Fwd) OR (Rev AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Pump : BOOL;
    Run : BOOL;
    Stop : BOOL;
END_VAR

Pump := Run OR (Pump AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    OverloadOK : BOOL;
    Stop : BOOL;
END_VAR

Motor := (Start AND OverloadOK) OR (Motor AND NOT Stop AND OverloadOK);

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    OverloadOK : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop) AND OverloadOK;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
END_VAR

Motor := (Start OR (Motor AND NOT Stop)) AND NOT Overload;

END_PROGRAM

PROGRAM Main
VAR
    Motor : BOOL;
    Start : BOOL;
    Stop : BOOL;
